<script>
/* Keep exact local image paths for the HTML ZIP (not temporary browser blob URLs). */
const exportUrls={};
document.querySelectorAll('.image-input').forEach(e=>e.onchange=()=>{const f=e.files[0],k=e.dataset.image;if(!f)return;files[k]=f;const u=exportUrls[k]=URL.createObjectURL(f);if(k==='background')document.querySelector('.dc-hero').style.backgroundImage=`url(${u})`;else{const el=document.querySelector('#'+k+'Preview');el.classList.remove('hide');if(k==='profile')el.style.backgroundImage=`url(${u})`;else el.src=u;}});
document.querySelectorAll('.social').forEach(e=>e.oninput=()=>{const a=document.querySelector(`[data-social-out="${e.dataset.social}"]`);a.classList.toggle('hide',!e.value.trim());a.href=e.value||'#';const hasSocial=[...document.querySelectorAll('.social')].some(input=>input.value.trim());document.querySelector('.dc-body h4').classList.toggle('hide',!hasSocial);});
document.querySelectorAll('.social').forEach(e=>e.dispatchEvent(new Event('input')));
/* Optional details must disappear completely when their input is empty. */
document.querySelectorAll('[data-bind]').forEach(e=>e.oninput=()=>{const empty=!e.value.trim();document.querySelectorAll(`[data-out="${e.dataset.bind}"]`).forEach(o=>{o.textContent=e.value;const item=o.closest('.dc-info p')||o;item.classList.toggle('hide',empty);});});
document.querySelectorAll('[data-bind]').forEach(e=>e.dispatchEvent(new Event('input')));
document.querySelector('#exportHtml').onclick=async()=>{const zip=new JSZip(), clone=card.cloneNode(true);Object.entries(files).forEach(([k,f])=>{const name='images/'+k+'-'+f.name.replace(/[^a-z0-9.]/gi,'-');zip.file(name,f);const u=exportUrls[k];if(k==='background')clone.querySelector('.dc-hero').style.backgroundImage=`url(${name})`;else if(k==='profile')clone.querySelector('#profilePreview').style.backgroundImage=`url(${name})`;else clone.querySelector('#'+k+'Preview').src=name;});const html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Digital Card</title><link href="https://unpkg.com/boxicons@2.1.4/css/boxicons.min.css" rel="stylesheet"><link rel="stylesheet" href="style.css"></head><body><div class="preview-wrap">${clone.outerHTML}</div></body></html>`;zip.file('index.html',html);zip.file('style.css',document.querySelector('style').textContent);const blob=await zip.generateAsync({type:'blob'}),a=document.createElement('a');a.download='digital-card-html.zip';a.href=URL.createObjectURL(blob);a.click();};
</script>
<script>
/* The downloaded HTML receives the same empty-social hiding rule. */
document.querySelector('#exportHtml').onclick=async()=>{const zip=new JSZip(),clone=card.cloneNode(true);Object.entries(files).forEach(([k,f])=>{const n='images/'+k+'-'+f.name.replace(/[^a-z0-9.]/gi,'-');zip.file(n,f);if(k==='background')clone.querySelector('.dc-hero').style.backgroundImage=`url(${n})`;else if(k==='profile')clone.querySelector('#profilePreview').style.backgroundImage=`url(${n})`;else clone.querySelector('#'+k+'Preview').src=n;});const css=document.querySelector('style').textContent+'#digitalCard .dc-socials a.off{display:none!important}#digitalCard .dc-body h4{display:none}#digitalCard .dc-body:has(.dc-socials a:not(.off)) h4{display:block}';zip.file('style.css',css);zip.file('index.html',`<!doctype html><html><head><meta charset="utf-8"><link href="https://unpkg.com/boxicons@2.1.4/css/boxicons.min.css" rel="stylesheet"><link rel="stylesheet" href="style.css"></head><body><div class="preview-wrap">${clone.outerHTML}</div></body></html>`);const a=document.createElement('a');a.download='digital-card-html.zip';a.href=URL.createObjectURL(await zip.generateAsync({type:'blob'}));a.click();};
document.querySelectorAll('.social').forEach(e=>e.oninput=()=>{const empty=!e.value.trim(),a=document.querySelector(`[data-social-out="${e.dataset.social}"]`);a.classList.toggle('off',empty);a.classList.toggle('hide',empty);a.href=e.value||'#';document.querySelector('.dc-body h4').classList.toggle('hide',![...document.querySelectorAll('.social')].some(i=>i.value.trim()));});document.querySelectorAll('.social').forEach(e=>e.dispatchEvent(new Event('input')));
</script>
<script>
const exportHtmlUrl='{{ route('digital-cards.export-html') }}', csrfToken=document.querySelector('meta[name="csrf-token"]').content;
const setLoading=(button,loading,label)=>{button.disabled=loading;button.innerHTML=loading?'<span class="spinner-border spinner-border-sm me-1"></span> Preparing…':label;};
document.querySelector('#exportHtml').onclick=async function(){const button=this;setLoading(button,true,'<i class="bx bx-code-alt"></i> Export HTML ZIP');try{const clone=card.cloneNode(true),data=new FormData(),styles=[...document.querySelectorAll('style')].map(s=>s.textContent).join('\n');Object.entries(files).forEach(([key,file])=>{const path='images/'+file.name;data.append('images[]',file,file.name);if(key==='background')clone.querySelector('.dc-hero').style.backgroundImage=`url("${path}")`;else if(key==='profile')clone.querySelector('#profilePreview').style.backgroundImage=`url("${path}")`;else clone.querySelector('#'+key+'Preview').src=path;});data.append('html',`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Digital Card</title><link href="https://unpkg.com/boxicons@2.1.4/css/boxicons.min.css" rel="stylesheet"><link rel="stylesheet" href="style.css"></head><body><div class="preview-wrap">${clone.outerHTML}</div></body></html>`);data.append('css',styles);const response=await fetch(exportHtmlUrl,{method:'POST',headers:{'X-CSRF-TOKEN':csrfToken},body:data});if(!response.ok)throw new Error('ZIP could not be generated.');const a=document.createElement('a');a.href=URL.createObjectURL(await response.blob());a.download='digital-card-html.zip';a.click();URL.revokeObjectURL(a.href);}catch(error){alert(error.message);}finally{setLoading(button,false,'<i class="bx bx-code-alt"></i> Export HTML ZIP');}};
document.querySelector('#exportPng').onclick=async function(){const button=this;setLoading(button,true,'<i class="bx bx-image"></i> Download PNG');try{if(typeof html2canvas==='undefined')throw new Error('PNG export library is loading. Please check your internet connection and try again.');const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'}),a=document.createElement('a');a.download='digital-card.png';a.href=canvas.toDataURL('image/png');a.click();}catch(error){alert(error.message);}finally{setLoading(button,false,'<i class="bx bx-image"></i> Download PNG');}};
</script>
<script>
/* Capture-phase handler guarantees the ZIP action is not affected by older preview handlers. */
document.addEventListener('click', async function(event) {
  const button = event.target.closest('#exportHtml');
  if (!button) return;
  event.preventDefault(); event.stopImmediatePropagation();
  const original = button.innerHTML;
  button.disabled = true; button.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span> Preparing…';
  try {
    const preview = document.querySelector('#digitalCard'), clone = preview.cloneNode(true), data = new FormData();
    document.querySelectorAll('.image-input').forEach(input => {
      const file = input.files[0]; if (!file) return;
      const type = input.dataset.image, path = 'images/' + file.name;
      data.append('images[]', file, file.name);
      if (type === 'background') clone.querySelector('.dc-hero').style.backgroundImage = `url("${path}")`;
      else if (type === 'profile') clone.querySelector('#profilePreview').style.backgroundImage = `url("${path}")`;
      else clone.querySelector('#' + type + 'Preview').src = path;
    });
    data.append('html', `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Digital Card</title><link href="https://unpkg.com/boxicons@2.1.4/css/boxicons.min.css" rel="stylesheet"><link rel="stylesheet" href="style.css"></head><body><div class="preview-wrap">${clone.outerHTML}</div></body></html>`);
    data.append('css', [...document.querySelectorAll('style')].map(style => style.textContent).join('\n'));
    const response = await fetch('{{ route('digital-cards.export-html') }}', {method:'POST', headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content, 'Accept':'application/zip'}, body:data});
    if (!response.ok) throw new Error(await response.text() || 'ZIP export failed.');
    const link = document.createElement('a'); link.href = URL.createObjectURL(await response.blob()); link.download = 'digital-card-html.zip'; document.body.appendChild(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  } catch (error) { alert('HTML ZIP export failed. Please try again.'); }
  finally { button.disabled = false; button.innerHTML = original; }
}, true);
</script>
