const imageHints={profile:'Recommended: 800 × 800 px (square, JPG/PNG)',background:'Recommended: 1600 × 840 px (landscape banner, JPG/PNG)',logo:'Recommended: 500 × 500 px (transparent PNG preferred)',scanner:'Recommended: 800 × 800 px (square QR/scanner image, PNG/JPG)'};
