actions[1].onclick=()=>{const v='BEGIN:VCARD\nVERSION:3.0\nFN:'+get('name')+'\nTEL:'+get('phone')+'\nEMAIL:'+get('email')+'\nEND:VCARD';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([v],{type:'text/vcard'}));a.download='contact.vcf';a.click();};
actions[2].onclick=()=>navigator.share?navigator.share({title:get('name'),url:location.href}):navigator.clipboard.writeText(location.href);
actions[3].onclick=()=>open(mapLink.value||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(get('address')));
const scanner=document.querySelector('#scannerPreview'),modal=document.createElement('div');modal.className='scanner-modal';modal.innerHTML='<div class="scanner-modal-box"><button type="button">×</button><img alt="Scanner image"></div>';document.body.appendChild(modal);modal.onclick=e=>{if(e.target===modal||e.target.tagName==='BUTTON')modal.classList.remove('open')};
const scannerInput=document.querySelector('[data-image="scanner"]');scannerInput.onchange=()=>{const file=scannerInput.files[0];if(!file)return;const src=URL.createObjectURL(file);scanner.src=src;scanner.classList.add('hide');let trigger=document.querySelector('.scanner-launch');if(!trigger){trigger=document.createElement('button');trigger.type='button';trigger.className='scanner-launch';trigger.innerHTML='<i class="bx bx-qr"></i>';document.querySelector('#digitalCard').appendChild(trigger);trigger.onclick=()=>{modal.querySelector('img').src=scanner.src;modal.classList.add('open')}}};
document.querySelector('[data-image="profile"]').addEventListener('change', event => { document.querySelector('#profilePreview i').style.display = event.target.files[0] ? 'none' : ''; });
/* Default Technofra card content and bundled assets. */
const defaultCard={name:'Gopal Giri',role:'Founder & CEO',company:'Technofra',tagline:'Technology | Innovation | Growth',phone:'+91 80808 03374',email:'gopal@technofra.com',website:'www.technofra.com',address:'501 Ghanshyam Enclave Kandivali West'};
Object.entries(defaultCard).forEach(([key,value])=>{const input=document.querySelector(`[data-bind="${key}"]`);input.value=value;input.dispatchEvent(new Event('input'));});
mapLink.value='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(defaultCard.address);
const defaultAssets={profile:'{{ asset('assets/images/gopal.jpg') }}',background:'{{ asset('assets/images/banner.jpeg') }}',logo:'{{ asset('assets/images/technofra.png') }}'};
document.querySelector('#profilePreview').style.backgroundImage=`url("${defaultAssets.profile}")`;document.querySelector('#profilePreview i').style.display='none';document.querySelector('.dc-hero').style.backgroundImage=`url("${defaultAssets.background}")`;document.querySelector('#logoPreview').src=defaultAssets.logo;document.querySelector('#logoPreview').classList.remove('hide');
/* Add as many contact numbers, email IDs and addresses as required. */
const extraSetup={phone:{label:'Add another phone number',icon:'bx-phone',type:'tel',action:value=>location.href='tel:'+value},email:{label:'Add another email ID',icon:'bx-envelope',type:'email',action:value=>location.href='mailto:'+value},address:{label:'Add another address',icon:'bx-map',type:'text',action:value=>open(mapLink.value||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(value))}};
Object.entries(extraSetup).forEach(([kind,config])=>{const source=document.querySelector(`[data-bind="${kind}"]`).closest('.col-md-6');const add=document.createElement('button');add.type='button';add.className='btn btn-sm btn-outline-primary mt-2';add.innerHTML='<i class="bx bx-plus"></i> '+config.label;source.appendChild(add);add.onclick=()=>{const field=document.createElement('input');field.type=config.type;field.className='form-control mt-2 extra-'+kind;field.placeholder=kind==='address'?'Enter another address':'Enter another '+kind;source.appendChild(field);const row=document.createElement('p');row.className='extra-preview-'+kind;row.innerHTML=`<i class="bx ${config.icon}"></i><span></span>`;document.querySelector('.dc-info').appendChild(row);field.oninput=()=>{row.querySelector('span').textContent=field.value;row.classList.toggle('hide',!field.value.trim())};row.onclick=()=>config.action(field.value);field.dispatchEvent(new Event('input'));};});
/* Keep additional values on the same preview line, separated with a slash. */
Object.entries(extraSetup).forEach(([kind,config])=>{const source=document.querySelector(`[data-bind="${kind}"]`).closest('.col-md-6'),add=source.querySelector('button');add.onclick=()=>{const field=document.createElement('input');field.type=config.type;field.className='form-control mt-2 extra-'+kind;field.placeholder=kind==='address'?'Enter another address':'Enter another '+kind;source.appendChild(field);const refresh=()=>{const values=[document.querySelector(`[data-bind="${kind}"]`).value,...[...source.querySelectorAll('.extra-'+kind)].map(i=>i.value)].filter(v=>v.trim());const output=document.querySelector(`[data-out="${kind}"]`);output.textContent=values.join(' / ');output.closest('.dc-info p').classList.toggle('hide',!values.length);};field.oninput=refresh;source.querySelector(`[data-bind="${kind}"]`).oninput=refresh;refresh();};});
</script>
@endsection
